  "landing.046": { ar: "اختبارات بعد كل Lesson، تصحيص فوري، شرح للإجابات، ومتابعة متقدمة.", en: "A quiz after every lesson, instant grading, answer explanations, and advanced tracking." },
  "landing.047": { ar: "ملخصات لكل Lesson، PDFs قابلة للتحميل، ومواد إضافية منظمة.", en: "Summaries for every lesson, downloadable PDFs, and organized extra materials." },
  "landing.048": { ar: "الأهل يشوفوا مستوى الطالب، حضوره، واجباته، وتقارير شهرية مفصلة.", en: "Parents see the student's level, attendance, homework, and detailed monthly reports." },
