  "landing.054": { ar: "حاجة في كل ركن من المنصة", en: "Something in every corner of the platform" },
  "landing.055": { ar: "الكل شغّال فعلاً — من أول الحصة اللايف لحد ما يوصلك الـReport الشهري.", en: "Everything actually works — from the live class all the way to your monthly report." },
  "landing.056": { ar: "للأهل", en: "For parents" },
