  "landing.082": { ar: "الأسعار شاملة للـVAT. طرق الدفع: InstaPay (", en: "Prices include VAT. Payment methods: InstaPay (" },
  "landing.083": { ar: ") · Vodafone Cash (قريبًا)", en: ") · Vodafone Cash (coming soon)" },
  "landing.084": { ar: "المنصة دي لمين؟", en: "Who is this platform for?" },
  "landing.085": { ar: "لطلاب الصف الثاني الثانوي اللي عايزين يتعلموا Programming & AI بطريقة منظمة. الأهل كمان معاهم Dashboard خاص لمتابعة الأبناء.", en: "For 2nd-secondary students who want to learn Programming & AI in an organized way. Parents get their own dashboard to follow their children." },
  "landing.086": { ar: "إزاي بدأ؟", en: "How did it start?" },
  "landing.087": { ar: "تعمل حساب، تختار Group، تشترك، تدفع عن طريق InstaPay أو e& Cash على +20 1147422177، وبعد ما الـAdmin يؤكد الدفع يتفعل اشتراكك خلال 24 ساعة.", en: "Create an account, choose a group, subscribe, pay via InstaPay or e& Cash to +20 1147422177, and once the admin confirms payment your subscription activates within 24 hours." },
  "landing.088": { ar: "في Recordings بعد كل Live Session؟", en: "Are there recordings after every live session?" },
  "landing.089": { ar: "أيوا. كل حصة بتتسجل تلقائيًا، و Recording بيكون متاح لكل المشتركين النشطين.", en: "Yes. Every session is recorded automatically, and the recording is available to all active subscribers." },
  "landing.090": { ar: "أقدر أشوف المستوى بتاعي إزاي؟", en: "How can I see my level?" },
  "landing.091": { ar: "في Dashboard هتلاقي Course Progress، Attendance، نتائج Quizzes، Homework، وتقارير شهرية. والأهل يقدروا يشوفوا اللي بيعملوه.", en: "The dashboard shows course progress, attendance, quiz results, homework, and monthly reports. Parents can follow along too." },
  "landing.092": { ar: "إيه طرق الدفع؟", en: "What payment methods are there?" },
  "landing.093": { ar: "InstaPay و e& Cash على +20 1147422177 (تحويل يدوي وتبعت الـReference، والـAdmin يفعّل اشتراكك). Vodafone Cash قريبًا.", en: "InstaPay and e& Cash to +20 1147422177 (manual transfer — send the reference and the admin activates your subscription). Vodafone Cash coming soon." },
  "landing.094": { ar: "لو اشتراكي خلص إيه اللي بيحصل؟", en: "What happens when my subscription ends?" },
  "landing.095": { ar: "حسابك بيفضل موجود، لكن المحتوى التعليمي بيتقفل لحد ما تجدد الاشتراك. تقدر تجدد في أي وقت من الـDashboard.", en: "Your account stays, but learning content is locked until you renew. You can renew anytime from the dashboard." },
  "landing.096": { ar: "الأسئلة الشائعة", en: "FAQ" },
  "landing.097": { ar: "كل اللي محتاج تعرفه", en: "Everything you need to know" },
  "landing.098": { ar: "لو سؤالك مش هنا، تواصل معانا على WhatsApp.", en: "If your question isn't here, reach us on WhatsApp." },
  "landing.099": { ar: "طالبة 2nd Secondary", en: "2nd Secondary student" },
  "landing.100": { ar: "أخيراً منصة عربية محترمة تشرح الـMachine Learning بشكل بسيط. الـLive Sessions مريحة والـQuizzes بتثبت المعلومة.", en: "Finally a proper Arabic platform that explains Machine Learning simply. The live sessions are comfortable and the quizzes lock the knowledge in." },
  "landing.101": { ar: "أب طالب", en: "Parent" },
  "landing.102": { ar: "بقدر أشوف مستوى ابني كل أسبوع من غير ما أسأل. الـDashboard واضح والتقارير الشهرية ممتازة.", en: "I can see my son's level every week without asking. The dashboard is clear and the monthly reports are excellent." },
  "landing.104": { ar: "الـRecordings بتنقذني كتير لما بفوت حصة. الـPDFs والـSummaries بترجعلي المعلومة بسرعة.", en: "Recordings save me whenever I miss a class. The PDFs and summaries bring the information back fast." },
  "landing.105": { ar: "آراء", en: "Testimonials" },
  "landing.106": { ar: "طلابنا وأهلهم بيقولوا إيه", en: "What our students and parents say" },
